UPDATE fasi SET formula_secondi = '(se(qtSmd > 0, tempoRevisioneAoi, 0) + se(doppiaFaccia * qtSmdLatoB > 0, tempoRevisioneAoiLatoB, 0)) * nSchede' WHERE codice = 'ispezioneAOI' AND formula_secondi = '(se(qtSmd > 0, tempoRevisioneAoi, 0) + se(qtSmdLatoB > 0, tempoRevisioneAoiLatoB, 0)) * nSchede';
